/**
 * PL 7's "1001 Yogas" evaluator (docs/specs/pl_yogas.md). Conditions come
 * parsed from PL's own formulas (plYogaRules.json, generated by
 * scripts/gen_pl_yogas.mjs). Every atom starts on the Rashi chart unless it
 * names a varga (PL's binary letters: N/S → D9, D → D4, T → D7, K → D40 …).
 * Houses are whole signs from the reference (the Lagna, or the planet/sign in
 * "(…)REF"). Sets are existential. Atoms PL cannot decode are False (True
 * when negated), as in PL. Tokens whose meaning PL's code does not settle for
 * us throw `Unsupported`: the yoga is then reported as "not evaluated"
 * rather than guessed.
 */
import { isCombust } from '../combust';
import { DEBIL_SIGN, EXALT_SIGN, OWN, MT, inMt, nat, temp } from '../strength/common';
import { aspectValue } from '../strength/drik';
import { fwd, pid } from '../strength/common';
import { PLANETS, type ChartResult, type PlanetId } from '../types';
import { SIGN_LORD } from '../zodiac';
import { vargaSign, type VargaId } from '../varga/rules';
import type { Page1Strengths } from '../strength';

export class Unsupported extends Error {}

export interface Atom {
  atom: string; neg?: boolean; varga?: string; ref?: string; subj?: string; rel?: string; obj?: string;
  obj_varga?: string; quality?: string; quality_varga?: string; error?: string;
}
export type Cond = Atom | { op: 'or' | 'and' | 'and_low'; args: Cond[] };

export interface YogaContext {
  chart: ChartResult;
  strength: Page1Strengths | null;
  /** '@W' (female native): null = not set → atoms using it are not evaluated. */
  female: boolean | null;
  /** Hindu weekday of birth, 1 = Sunday (for '@sun' … '@sat'); null if unknown. */
  weekday?: number | null;
}
const WEEKDAY: Record<string, number> = { '@sun': 1, '@mon': 2, '@tue': 3, '@wed': 4, '@thu': 5, '@fri': 6, '@sat': 7 };

const SEVEN: PlanetId[] = ['Su', 'Mo', 'Ma', 'Me', 'Ju', 'Ve', 'Sa'];
const NUM: Record<string, PlanetId> = { 1: 'Su', 2: 'Mo', 3: 'Ma', 4: 'Me', 5: 'Ju', 6: 'Ve', 7: 'Sa', 8: 'Ra', 9: 'Ke' };
const VARGA_OF: Record<string, VargaId> = { D1: 'D1', D2: 'D2', D3: 'D3', D4: 'D4', D7: 'D7', D9: 'D9', D10: 'D10', D12: 'D12', D16: 'D16', D20: 'D20', D24: 'D24', D27: 'D27', D30: 'D30', D40: 'D40', D45: 'D45', D60: 'D60' };
const FULL: Partial<Record<PlanetId, number[]>> = { Ma: [4, 8], Ju: [5, 9], Sa: [3, 10], Ra: [5, 9], Ke: [5, 9] };
const NAT_MALEFIC: PlanetId[] = ['Su', 'Ma', 'Sa', 'Ra', 'Ke'];

const m12 = (x: number) => ((x % 12) + 12) % 12;
const count = (from: number, to: number) => m12(to - from) + 1;

class Ev {
  constructor(readonly x: YogaContext) {}
  private get c() { return this.x.chart; }

  vsign(p: PlanetId, v: VargaId = 'D1'): number { return vargaSign(v, this.c.bodies[p].lon); }
  lagna(v: VargaId = 'D1'): number { return vargaSign(v, this.c.asc.lon); }
  waxing(): boolean { return fwd(this.c.bodies.Su.lonDeg, this.c.bodies.Mo.lonDeg) <= 180; }

  /** PL dignity code 1 Exalted … 9 Debilitated; Rasi uses PL's tables with MT degrees, a varga only signs. */
  dignity(p: PlanetId, v: VargaId = 'D1'): number {
    const s = this.vsign(p, v);
    if (s === EXALT_SIGN[p]) return 1;
    if (s === DEBIL_SIGN[p]) return 9;
    if (v === 'D1' && inMt(p, this.c.bodies[p].lonDeg)) return 2;
    if (v !== 'D1' && s === MT[p][0]) return 2;
    if (OWN[p].includes(s)) return 3;
    const lord = SIGN_LORD[s]!;
    const r = nat(p, lord) + temp(this.vsign(p, v), this.vsign(lord, v));
    return ({ 2: 4, 1: 5, 0: 6, [-1]: 7, [-2]: 8 } as Record<number, number>)[r]!;
  }
  ratio(p: PlanetId): number {
    if (p === 'Ra' || p === 'Ke') return 1;
    const r = this.x.strength?.planets[p].sbRatio;
    if (r == null) throw new Unsupported('shadbala');
    return r;
  }
  combust(p: PlanetId): boolean { return p !== 'Su' && isCombust(this.c.bodies[p], this.c.bodies.Su); }
  naturalBenefic(p: PlanetId): boolean {
    if (p === 'Ju' || p === 'Ve') return true;
    if (p === 'Mo') return this.waxing();
    if (p === 'Me') return !NAT_MALEFIC.some((q) => this.vsign(q) === this.vsign('Me'));
    return false;
  }
  karaka(label: 'AK' | 'AmK'): PlanetId {
    const k = this.x.strength?.planets;
    if (!k) throw new Unsupported('karakas');
    return SEVEN.find((p) => k[p].k7 === label)!;
  }
  /** Lord of the nth house from a reference sign. */
  lordFrom(refSign: number, n: number): PlanetId { return SIGN_LORD[m12(refSign + n - 1)]!; }
  /** Full sign aspect (quarter value 4) of `by` (in sign sb) on sign st. */
  fullAspect(by: PlanetId, sb: number, st: number): boolean {
    const n = count(sb, st);
    return n === 7 || (FULL[by] ?? []).includes(n);
  }

  /** Graha-set token → planets. `ref` = reference sign (for L<n> inside parens). */
  grahas(tok: string, refSign: number, v: VargaId, subjSet?: PlanetId[]): PlanetId[] {
    if (/^[1-9]$/.test(tok)) return [NUM[tok]!];
    if (/^1[0-6]$/.test(tok)) throw new Unsupported('special point');
    switch (tok) {
      case '%': return SEVEN;
      case '&': return [...PLANETS];
      case '$': return [this.karaka('AK')];
      case 'º': return [this.karaka('AmK')];
      case 'ï': return PLANETS.filter((p) => { const d = this.dignity(p, v); return d === 1 || d === 3; });
      case 'á': return ['Me', 'Sa'];
      case 'B': return PLANETS.filter((p) => this.naturalBenefic(p));
      case 'BE': return PLANETS.filter((p) => this.naturalBenefic(p) && this.dignity(p, v) === 1);
      case 'BO': return PLANETS.filter((p) => this.naturalBenefic(p) && [2, 3].includes(this.dignity(p, v)));
      case 'BS': return PLANETS.filter((p) => this.naturalBenefic(p) && this.ratio(p) >= 1);
      case 'BU': return PLANETS.filter((p) => this.naturalBenefic(p) && this.dignity(p, v) <= 5);
      case 'm': return PLANETS.filter((p) => !this.naturalBenefic(p));
      case 'mS': return PLANETS.filter((p) => !this.naturalBenefic(p) && this.ratio(p) > 1);
      case 'O': return PLANETS.filter((p) => this.dignity(p, v) === 3);
      case 'E': return PLANETS.filter((p) => this.dignity(p, v) === 1);
      case 'ee': return PLANETS.filter((p) => this.dignity(p, v) === 7);
      case 't': return PLANETS.filter((p) => this.dignity(p, v) === 9);
      case 'b': return PLANETS.filter((p) => this.combust(p));
      case 'X': return SEVEN.filter((p) => this.ratio(p) >= 1);
      case 'XX': return [SEVEN.reduce((a, b) => (this.ratio(b) > this.ratio(a) ? b : a))];
      case 'F': if (!subjSet) throw new Unsupported('F'); return PLANETS.filter((q) => subjSet.some((p) => p !== q && nat(p, q) > 0));
      case 'e': if (!subjSet) throw new Unsupported('e'); return PLANETS.filter((q) => subjSet.some((p) => p !== q && nat(p, q) < 0));
      case '.D': return ['Ma', 'Me', 'Ju', 'Ve', 'Sa'];
      case '.N': return ['Ra', 'Ke'];
      case '.M': return ['Su', 'Ma', 'Ju'];
      case '.F': return ['Mo', 'Ve'];
      case '.l': return ['Su', 'Mo'];
      case '.A': return [6, 8, 12].map((n) => this.lordFrom(this.lagna(), n));
      case '.E': return PLANETS.filter((p) => this.dignity(p, 'D9') === 1);
      case '.t': return PLANETS.filter((p) => this.dignity(p, 'D9') === 9);
      case '.r': return PLANETS.filter((p) => this.c.bodies[p].retrograde);
      case '.Y': case '.y': return []; // PL 7.0.1 clears the war flags
      case 'LK': return [1, 4, 7, 10].map((n) => this.lordFrom(this.lagna(), n));
      case 'LT': return [5, 9].map((n) => this.lordFrom(this.lagna(), n));
    }
    let mm: RegExpMatchArray | null;
    if ((mm = /^L(\d{1,2})$/.exec(tok))) return [this.lordFrom(refSign, +mm[1]!)];
    if ((mm = /^LL(\d{1,2})$/.exec(tok))) return [this.lordFrom(this.lagna(), +mm[1]!)];
    if (tok === 'LN') return [SIGN_LORD[this.vsign(this.lordFrom(this.lagna(), 10), 'D9')]!];
    if ((mm = /^LE(.+)$/.exec(tok))) {
      const g = this.grahas(mm[1]!, refSign, v);
      return PLANETS.filter((q) => g.some((p) => EXALT_SIGN[q] === this.vsign(p, v) && q !== 'Ra' && q !== 'Ke'));
    }
    if ((mm = /^ã(N?)(.+)$/.exec(tok))) {
      const vv: VargaId = mm[1] ? 'D9' : v;
      return this.grahas(mm[2]!, refSign, v).map((p) => SIGN_LORD[this.vsign(p, vv)]!);
    }
    throw new Unsupported(`graha ${tok}`);
  }

  rashis(tok: string): number[] {
    let mm: RegExpMatchArray | null;
    if ((mm = /^R(\d{1,2})$/.exec(tok))) return [+mm[1]! - 1];
    const all = Array.from({ length: 12 }, (_, i) => i);
    switch (tok) {
      case 'RB': case 'RZ': case 'Z': return all.filter((s) => s % 2 === 1);
      case 'Ra': case 'Rz': return all.filter((s) => s % 2 === 0);
      case 'RF': case 'Rf': return [1, 4, 7, 10];
      case 'RM': case 'Rm': return [0, 3, 6, 9];
      case 'Rd': return [2, 5, 8, 11];
      case 'RP': return [0, 1, 3, 8, 9];
      case 'RS': return [2, 4, 5, 6, 7, 10];
      case 'RTa': return [2, 6, 10];
      case 'RTe': return [1, 5, 9];
      case 'RTf': return [0, 4, 8];
      case 'RTw': return [3, 7, 11];
      case 'Ln': return [this.lagna()];
      case 'Ls': return [this.lagna('D9')];
      case 'Lk': return [this.vsign(this.karaka('AK'), 'D9')];
    }
    throw new Unsupported(`rashi ${tok}`);
  }

  bhavas(tok: string): number[] {
    let mm: RegExpMatchArray | null;
    if ((mm = /^!?(\d{1,2})$/.exec(tok))) { const n = +mm[1]!; if (n < 1 || n > 12) throw new Unsupported(`house ${n}`); return [n]; }
    switch (tok) {
      case 'a': return [6, 8, 12];
      case '!K': return [1, 4, 7, 10];
      case '!T': return [5, 9];
      case '!D': return [2, 5, 8, 11];
      case '!A': return [3, 6, 9, 12];
      case '!U': return [3, 6, 10, 11];
      case '!C': return [4, 8];
    }
    throw new Unsupported(`bhava ${tok}`);
  }

  quality(p: PlanetId, q: string, v: VargaId, refSign: number): boolean {
    let mm: RegExpMatchArray | null;
    if (/^[1-9]$/.test(q)) return this.dignity(p, v) === +q;
    const d = () => this.dignity(p, v);
    const house = () => count(refSign, this.vsign(p, v));
    switch (q) {
      case 'ï': return d() <= 3;
      case 'E': return d() === 1;
      case 'M': return d() === 2;
      case 'O': return d() === 2 || d() === 3;
      case 'G': return d() === 4;
      case 'F': return d() === 5;
      case 'n': return d() === 6;
      case 'e': return d() === 7 || d() === 8;
      case 'g': return d() === 8;
      case 'U': return d() < 6;
      case 'u': return d() > 6;
      case 'd': return d() === 9;
      case 'S': case 'P': case 'p': return this.ratio(p) >= 1;
      case 'v': case 'x': return this.ratio(p) < 1;
      case 'c': case 'cm': return this.combust(p);
      case 'K': return [1, 4, 7, 10].includes(house());
      case 'T': return [5, 9].includes(house());
      case 'W': return this.waxing();
      case 'w': return !this.waxing();
      case '=': case 'è': return this.vsign(p) === this.vsign(p, 'D9');
      case 'ð': return [7, 8, 9].includes(d()) || this.combust(p);
      case 'V': { const s = this.x.strength?.planets[p].vimshopakaScore; if (s == null) throw new Unsupported('vimshopaka'); return s >= 15; }
      case 'Qr': return this.c.bodies[p].retrograde;
      case 'Qw': return [3, 11].includes(this.vsign(p));
      case 'h': case 'H': {
        const order = [...PLANETS].sort((a, b) => this.c.bodies[a].lonDeg - this.c.bodies[b].lonDeg);
        const i = order.indexOf(p), prev = order[(i + 8) % 9]!, next = order[(i + 1) % 9]!;
        const want = q === 'H';
        return this.naturalBenefic(prev) === want && this.naturalBenefic(next) === want;
      }
      case '·': case 'ë': return false;
    }
    if ((mm = /^º(\d+)$/.exec(q))) { const deg = this.c.bodies[p].lonDeg % 30; return deg >= +mm[1]! - 1 && deg < +mm[1]!; }
    throw new Unsupported(`quality ${q}`);
  }

  special(tok: string): boolean {
    let mm: RegExpMatchArray | null;
    if ((mm = /^Re(\d+)$/.exec(tok))) {
      const occ = new Set(SEVEN.map((p) => this.vsign(p)));
      return 12 - occ.size === +mm[1]!;
    }
    switch (tok) {
      case '@W': if (this.x.female === null) throw new Unsupported('sex'); return this.x.female;
      case '@bN': return fwd(this.c.asc.lonDeg, this.c.bodies.Su.lonDeg) < 180;
      case '@bD': return fwd(this.c.asc.lonDeg, this.c.bodies.Su.lonDeg) >= 180;
      case '@bK': return !this.waxing();
      case '@bS': return this.waxing();
    }
    if (tok in WEEKDAY) { if (!this.x.weekday) throw new Unsupported('weekday'); return this.x.weekday === WEEKDAY[tok]; }
    throw new Unsupported(`special ${tok}`);
  }

  atom(a: Atom): boolean {
    if (a.error) return !!a.neg;
    const v: VargaId = a.varga ? (VARGA_OF[a.varga] ?? (() => { throw new Unsupported(`varga ${a.varga}`); })()) : 'D1';
    let refSign = this.lagna(v);
    if (a.ref) {
      if (/^R?\d/.test(a.ref) && a.ref.startsWith('R')) refSign = this.rashis(a.ref)[0]!;
      else if (a.ref === 'Lk' || a.ref === 'Ln') refSign = this.rashis(a.ref)[0]!;
      else {
        const g = this.grahas(a.ref, this.lagna(v), v);
        if (g.length !== 1) throw new Unsupported(`ref ${a.ref}`);
        refSign = this.vsign(g[0]!, v);
      }
    }
    const r = this.rel(a, v, refSign);
    return a.neg ? !r : r;
  }

  rel(a: Atom, v: VargaId, refSign: number): boolean {
    const subj = a.subj ?? '', obj = a.obj ?? '';
    const ov: VargaId = a.obj_varga ? (VARGA_OF[a.obj_varga] ?? 'D1') : v;
    if (a.rel === 'special') return this.special(subj.replace(/^special:/, ''));
    if (subj.startsWith('point:')) throw new Unsupported(subj);
    if (subj.startsWith('rashi_set:')) {
      const signs = this.rashis(subj.slice(10));
      switch (a.rel) {
        case 'sign_in_set': { const set = this.rashis(obj.replace(/^rashi_set:/, '')); return signs.some((s) => set.includes(s)); }
        case 'sign_aspected_by': return this.grahas(obj, refSign, v).some((g) => signs.some((s) => this.fullAspect(g, this.vsign(g, v), s)));
        case 'sign_occupied_by': return this.grahas(obj, refSign, v).some((g) => signs.includes(this.vsign(g, v)));
      }
      throw new Unsupported(`rashi rel ${a.rel}`);
    }
    if (subj.startsWith('bhava_set:')) {
      const houses = this.bhavas(subj.slice(10)).map((h) => m12(refSign + h - 1));
      const gs = () => this.grahas(obj, refSign, v);
      switch (a.rel) {
        case 'house_aspected_by': return gs().some((g) => houses.some((s) => this.fullAspect(g, this.vsign(g, v), s)));
        case 'house_occupied_or_aspected_by': return gs().some((g) => houses.some((s) => this.vsign(g, v) === s || this.fullAspect(g, this.vsign(g, v), s)));
      }
      throw new Unsupported(`bhava rel ${a.rel}`);
    }
    const S = this.grahas(subj, refSign, v);
    switch (a.rel) {
      case 'in_house': { const hs = this.bhavas(obj.replace(/^bhava_set:/, '')); return S.some((p) => hs.includes(count(refSign, this.vsign(p, v)))); }
      case 'in_sign': { const ss = this.rashis(obj.replace(/^rashi_set:/, '')); return S.some((p) => ss.includes(this.vsign(p, v))); }
      case 'quality': {
        const qv: VargaId = a.quality_varga ? (a.quality_varga === 'D9' ? 'D2' : (VARGA_OF[a.quality_varga] ?? v)) : v;
        return S.some((p) => this.quality(p, a.quality!, qv, refSign));
      }
      case 'in_state': throw new Unsupported('state');
    }
    const O = this.grahas(obj, refSign, ov, S);
    const pairs = (f: (p: PlanetId, q: PlanetId) => boolean) => S.some((p) => O.some((q) => f(p, q)));
    switch (a.rel) {
      case 'is': return pairs((p, q) => p === q);
      case 'conjunct': return pairs((p, q) => p !== q && this.vsign(p, v) === this.vsign(q, ov));
      case 'aspected_by': return pairs((p, q) => p !== q && this.fullAspect(q, this.vsign(q, ov), this.vsign(p, v)));
      case 'conj_or_aspected_by': return pairs((p, q) => p !== q && (this.vsign(p, v) === this.vsign(q, ov) || this.fullAspect(q, this.vsign(q, ov), this.vsign(p, v))));
      case 'associated': return pairs((p, q) => p !== q && (this.vsign(p, v) === this.vsign(q, ov) || this.fullAspect(q, this.vsign(q, ov), this.vsign(p, v)) || SIGN_LORD[this.vsign(p, v)] === q));
      case 'exchange': return pairs((p, q) => p !== q && SIGN_LORD[this.vsign(p, v)] === q && SIGN_LORD[this.vsign(q, ov)] === p);
      case 'related_r': return pairs((p, q) => p !== q && (
        aspectValue(fwd(this.c.bodies[q].lonDeg, this.c.bodies[p].lonDeg), pid(q)) > 50
        || this.vsign(p, v) === this.vsign(q, ov)
        || (SIGN_LORD[this.vsign(p, v)] === q && SIGN_LORD[this.vsign(q, ov)] === p)));
    }
    throw new Unsupported(`relation ${a.rel}`);
  }

  /** Three-valued: null = depends on a token we cannot evaluate. */
  cond(c: Cond): boolean | null {
    if ('atom' in c) {
      try { return this.atom(c); } catch (e) { if (e instanceof Unsupported) { this.unknown.add(e.message); return null; } throw e; }
    }
    const vals = c.args.map((x) => this.cond(x));
    if (c.op === 'or') return vals.includes(true) ? true : vals.includes(null) ? null : false;
    return vals.includes(false) ? false : vals.includes(null) ? null : true;
  }
  readonly unknown = new Set<string>();
}

export type YogaOutcome = 'present' | 'absent' | 'unknown';
export function evaluateYoga(cond: Cond, x: YogaContext): { outcome: YogaOutcome; reason?: string } {
  const ev = new Ev(x);
  const r = ev.cond(cond);
  return r === null ? { outcome: 'unknown', reason: [...ev.unknown].join(', ') } : { outcome: r ? 'present' : 'absent' };
}
